import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Confirm","description":"","frontmatter":{},"headers":[],"relativePath":"components/confirm.md","filePath":"components/confirm.md"}'),n={name:"components/confirm.md"};function r(c,e,i,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="confirm" tabindex="-1">Confirm <a class="header-anchor" href="#confirm" aria-label="Permalink to &quot;Confirm&quot;">​</a></h1><p>Confirm is a modal that asks before an action.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it before an action that removes something or cannot be undone, and before one whose effect reaches other people. The title is the question (&quot;Delete 4 items?&quot;) and the message says what happens. A destructive action is <code>danger</code>; its button is the one red fill a Footer may hold.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>false</code></td><td>Whether it is open (bindable)</td></tr><tr><td><code>title</code></td><td>required</td><td>The question</td></tr><tr><td><code>message</code></td><td></td><td>One paragraph of body</td></tr><tr><td><code>children</code></td><td></td><td>A body in place of the message</td></tr><tr><td><code>confirmLabel</code></td><td>the <code>confirm</code> message</td><td>The name of the action</td></tr><tr><td><code>cancelLabel</code></td><td>the <code>cancel</code> message</td><td>The name of cancel</td></tr><tr><td><code>danger</code></td><td><code>false</code></td><td>A destructive action: the button is <code>danger-fill</code></td></tr><tr><td><code>busy</code></td><td><code>false</code></td><td>The action is running: its button is dimmed</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>The action cannot run yet</td></tr><tr><td><code>onconfirm</code></td><td>required</td><td>Called when the action is confirmed</td></tr><tr><td><code>oncancel</code></td><td></td><td>Called once when it closes without confirming</td></tr><tr><td><code>inline</code></td><td><code>false</code></td><td>The same surface in the flow, for documentation</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is a small <a href="./modal">Modal</a> (25rem) in the centre of every screen, gap-md from its edges, with the role <code>alertdialog</code>. The Footer holds cancel, then the action as <code>primary</code> or <code>danger-fill</code>. It opens with the focus on cancel, so Enter does not confirm by accident. Escape and the close button close it and call <code>oncancel</code>; a press on the scrim does nothing. Confirming calls <code>onconfirm</code> and leaves it open: the application shows <code>busy</code> while the work runs and sets <code>open</code> to false when it is done.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/confirm/" title="Confirm" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/confirm/" target="_blank" rel="noopener">Confirm</a></figcaption></figure>',10)])])}const p=t(n,[["render",r]]);export{f as __pageData,p as default};
